INSERT INTO public.flyway_schema_history VALUES (2, '2', 'datos', 'SQL', 'V2__datos.sql', -1739421149, 'wolverine307', '2025-06-05 13:54:48.475129', 149, true);
INSERT INTO public.sagas VALUES ('s001', 'La trilogía cinematográfica de El Señor de los Anillos, basada en la novela homónima del escritor británico J. R. R. Tolkien, comprende tres películas épicas de fantasía, acción y aventuras: El Señor de los Anillos: la Comunidad del Anillo (2001), El Señor de los Anillos: las dos torres (2002) y El Señor de los Anillos: el retorno del Rey (2003).
INSERT INTO public.sagas VALUES ('s002', 'Star Wars, conocida también en español como La guerra de las galaxias, es una franquicia de medios de fantasía compuesta primordialmente de una serie de películas concebidas por el cineasta estadounidense George Lucas en la década de 1970, y producidas y distribuidas inicialmente por 20th Century Fox y posteriormente por The Walt Disney Company a partir de 2012. Su trama describe las vivencias de un grupo de personajes que habitan en una galaxia ficticia e interactúan con elementos como «la Fuerza», un campo de energía metafísico y omnipresente que posee un «lado luminoso» impulsado por la sabiduría, la nobleza y la justicia y utilizado por los Jedi, y un «lado oscuro» usado por los Sith y provocado por la ira, el miedo, el odio y la desesperación.', NULL, '1977-05-25', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcREHA9BWCRD8LBeUe498kzy7ciKcIfpXc7oXw&s', false, 'Star Wars');
INSERT INTO public.sagas VALUES ('s003', 'Harry Potter es una serie de novelas fantásticas escrita por la autora británica J. K. Rowling, en la que se describen las aventuras del joven aprendiz de magia y hechicería Harry Potter y sus amigos Hermione Granger y Ron Weasley, durante los años que pasan en el Colegio Hogwarts de Magia y Hechicería. El argumento se centra en la lucha entre Harry Potter y el malvado mago Lord Voldemort, quien asesinó a los padres de Harry en su afán de conquistar el mundo mágico.
INSERT INTO public.sagas VALUES ('s100', 'El Universo Cinematográfico de Marvel (MCU) es una franquicia de películas de superhéroes basadas en personajes de Marvel Comics. Comenzó con Iron Man en 2008 y ha crecido para incluir múltiples fases de películas interconectadas.', NULL, '2008-05-02', 'https://m.media-amazon.com/images/I/91iqen3IYJL.jpg', false, 'Marvel Cinematic Universe');
INSERT INTO public.sagas VALUES ('s005', 'James Bond es un personaje de ficción creado por el periodista y novelista inglés Ian Fleming en 1953. James Bond es el protagonista de la serie de novelas, películas, cómics y videojuegos homónimos, en las que protagoniza sus propias misiones como James Bond. Su profesión le otorga la denominación de agente encubierto con «licencia para matar», afiliado al servicio secreto de inteligencia británico, conocido actualmente como MI6.', NULL, '1962-10-05', 'https://m.media-amazon.com/images/I/71T2aDKfmIL.jpg', false, 'James Bond');
INSERT INTO public.sagas VALUES ('s006', 'El padrino es el nombre que reciben las películas dirigidas por Francis Ford Coppola y escritas por él mismo junto con el novelista Mario Puzo. La trilogía consta de las tres películas: El padrino, El padrino II y El padrino III. La primera entrega ganó tres premios Óscar (mejor película, mejor actor para Marlon Brando y mejor guion adaptado) de once candidaturas posibles, mientras que la segunda entrega ganó seis (mejor película, mejor director para Coppola, mejor actor de reparto para Robert De Niro, mejor guion adaptado, mejor banda sonora y mejor dirección artística) de once nominaciones posibles, en total nueve premios Óscar. Por su parte, la tercera no tuvo la misma repercusión de público, y además obtuvo siete nominaciones al Óscar pero no consiguió ningún premio.', '1990-12-25', '1972-03-24', 'https://image.tmdb.org/t/p/w500/r4gnMXoY1efvaolNDjn3nj4046S.jpg', true, 'El Padrino');
INSERT INTO public.sagas VALUES ('s007', 'La trilogía de The Dark Knight (titulada El caballero oscuro en España y Batman: el caballero de la noche en Hispanoamérica) es una trilogía cinematográfica de superhéroes, basada en el personaje Batman de DC Comics. La trilogía consistió en Batman Begins (2005), The Dark Knight (2008), y The Dark Knight Rises (2012), dirigidas, producidas y escritas principalmente por Christopher Nolan.
INSERT INTO public.sagas VALUES ('s008', 'Matrix es una tetralogía de películas de ciencia ficción escritas y dirigidas por las hermanas Wachowski. Se compone de The Matrix (1999), The Matrix Reloaded (2003), The Matrix Revolutions (2003) y The Matrix Resurrections (2021) y están protagonizadas en sus papeles principales por Keanu Reeves, Laurence Fishburne, Carrie-Anne Moss y Hugo Weaving.
INSERT INTO public.sagas VALUES ('s010', 'El "universo de Tarantino" o "universos de Tarantino" no es una saga en el sentido tradicional, sino una serie de películas que se conectan entre sí mediante personajes, referencias y elementos estilísticos. Existen dos tipos principales de universos: el "más real que la realidad" y el "universo cinematográfico".
INSERT INTO public.sagas VALUES ('s012', 'Indiana Jones es una franquicia de medios concebida por el cineasta estadounidense George Lucas y producida por Lucasfilm, cuyo argumento relata primordialmente las vivencias del aventurero homónimo ficticio para localizar objetos de relevancia histórica tales como el Arca de la Alianza y el Santo Grial, a la vez que se enfrenta a adversarios nazis y soviéticos para evitar que utilicen tales reliquias con fines siniestros.[', '2023-06-30', '1981-06-12', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcS6y6M128p9P5KE_NVlnMUSWtmI-6LUiQCgng&s', false, 'Indiana Jones');
INSERT INTO public.sagas VALUES ('s013', 'Parque Jurásico (Jurassic Park en inglés) es una franquicia literaria, cinematográfica y de videojuegos que comenzó con la novela de mismo título del escritor estadounidense Michael Crichton, publicada por primera vez en Estados Unidos en 1990. Posteriormente fue adaptada como una película del mismo nombre dirigida por Steven Spielberg. Es considerada a menudo como un relato de preocupación sobre la manipulación biológica del mismo modo que lo hizo la novela Frankenstein de Mary Shelley en su tiempo. En este relato se utiliza el concepto matemático de la teoría del caos y sus implicaciones filosóficas para explicar el colapso de un parque de atracciones que tiene como espectáculo principal ciertas especies de dinosaurios recreadas artificialmente.', '2022-06-10', '1993-06-11', 'https://m.media-amazon.com/images/I/71X6YzwV0gL._AC_UF1000,1000_QL80_.jpg', false, 'Jurassic Park');
INSERT INTO public.sagas VALUES ('s014', 'Misión: Imposible es una serie de películas de acción y espionaje estadounidense basada en la serie televisiva del mismo título. La serie es coproducida y protagonizada por Tom Cruise como Ethan Hunt, un agente de la ficticia Fuerza de Misiones Imposibles (IMF).
INSERT INTO public.sagas VALUES ('s015', 'Fast & Furious (también conocida como Rápidos y furiosos en Hispanoamérica, y The Fast and Furious: A todo gas en España) es una franquicia de medios estadounidense centrada en una serie de películas de acción que se ocupan en gran medida de automóviles. La saga también incluye cortometrajes, una serie de televisión, espectáculos en vivo, videojuegos y atracciones de parques temáticos. Está distribuida por Universal Pictures. Si bien la saga ha tenido una baja muy importante del elenco con la muerte de Paul Walker en 2013, Vin Diesel continuó con las series de películas que le prometió al actor ya fallecido, recalcando que junto con el resto del elenco consideran que aun la saga está muy activa.', NULL, '2001-06-22', 'https://www.universalpictures.es/tl_files/content/movies/fast9/fast9_header_mobile.jpg', false, 'Fast & Furious');
INSERT INTO public.sagas VALUES ('s016', 'Una saga de fantasía épica creada por George R.R. Martin que incluye las novelas "Juego de Tronos" y sus secuelas, adaptadas a la televisión como "Game of Thrones" y su precuela "House of the Dragon". La historia se desarrolla en los continentes ficticios de Poniente y Essos, siguiendo las luchas de poder entre familias nobles por el control del Trono de Hierro.', '2022-08-21', '2011-04-17', 'https://m.media-amazon.com/images/M/MV5BN2IzYzBiOTQtNGZmMi00NDI5LTgxMzMtN2EzZjA1NjhlOGMxXkEyXkFqcGdeQXVyNjAwNDUxODI@._V1_.jpg', false, 'Canción de Hielo y Fuego');
INSERT INTO public.producciones VALUES ('pr018', 3, 175, '1972-03-24', 'https://image.tmdb.org/t/p/w500/r4gnMXoY1efvaolNDjn3nj4046S.jpg', 'El padrino (título original en inglés: The Godfather) es una película estadounidense de 1972 dirigida por Francis Ford Coppola. La película fue producida por Albert S. Ruddy, de la compañía Paramount Pictures. Está basada en la novela homónima (que a su vez está basada en la familia real de los Mortillaro de Sicilia, Italia) de Mario Puzo, quien adaptó el guion junto a Coppola y Robert Towne, este último sin ser acreditado. Protagonizada por Marlon Brando y Al Pacino como los líderes de una poderosa familia criminal ficticia de Nueva York, la historia, ambientada desde 1945 a 1955, cuenta las crónicas de la familia Corleone liderada por Vito Corleone (Brando), enfocándose en el personaje de Michael Corleone (Pacino), y su transformación de un reacio joven ajeno a los asuntos familiares a un implacable jefe de la mafia ítalo-estadounidense.', 8.6, 'América, años 40. Don Vito Corleone (Marlon Brando) es el respetado y temido jefe de una de las cinco familias de la mafia de Nueva York. Tiene cuatro hijos: Connie (Talia Shire), el impulsivo Sonny (James Caan), el pusilánime Fredo (John Cazale) y Michael (Al Pacino), que no quiere saber nada de los negocios de su padre. Cuando Corleone, en contra de los consejos de ''Il consigliere'' Tom Hagen (Robert Duvall), se niega a participar en el negocio de las drogas, el jefe de otra banda ordena su asesinato. Empieza entonces una violenta y cruenta guerra entre las familias mafiosas.', 'PELICULA', 'El Padrino', 's006');
INSERT INTO public.producciones VALUES ('pr019', 2, 152, '2008-07-18', 'https://image.tmdb.org/t/p/w500/qJ2tW6WMUDux911r6m7haRef0WH.jpg', 'Segunda película de la trilogía de Nolan.', 6.5, 'Batman tiene que aceptar la ayuda de un nuevo fiscal para combatir a un criminal anarquista conocido como el Joker.', 'PELICULA', 'El Caballero Oscuro', 's007');
INSERT INTO public.producciones VALUES ('pr020', 4, 154, '1994-10-14', 'https://m.media-amazon.com/images/I/81UTs3sC5hL._AC_UF894,1000_QL80_.jpg', 'Ganadora de la Palma de Oro en Cannes.', 8.5, 'Las vidas de dos sicarios, un boxeador, la esposa de un gánster y dos bandidos se entrelazan en cuatro historias de violencia y redención.', 'PELICULA', 'Pulp Fiction', 's010');
INSERT INTO public.producciones VALUES ('pr021', 2, 142, '1994-07-06', 'https://media.es.wired.com/photos/6679bb407faf643236b6024c/2:3/w_576,h_864,c_limit/Forrest%20Gump.jpg', 'Ganadora de 6 premios Oscar.', 6.5, 'La presidencia de Kennedy y Johnson, Vietnam, Watergate y otros eventos históricos se desarrollan desde la perspectiva de un hombre de Alabama con un coeficiente intelectual de 75.', 'PELICULA', 'Forrest Gump', NULL);
INSERT INTO public.producciones VALUES ('pr022', 2, 148, '2010-07-16', 'https://m.media-amazon.com/images/M/MV5BMjExMjkwNTQ0Nl5BMl5BanBnXkFtZTcwNTY0OTk1Mw@@._V1_.jpg', 'Dirigida por Christopher Nolan.', 6.5, 'Un ladrón que roba secretos corporativos a través del uso de la tecnología de compartir sueños es encargado con la tarea inversa de implantar una idea en la mente de un CEO.', 'PELICULA', 'Inception', NULL);
INSERT INTO public.producciones VALUES ('pr023', 2, 136, '1999-03-31', 'https://m.media-amazon.com/images/M/MV5BNGE1YzI4NzMtZTUxNi00Y2I5LTg2MmQtODE0NThmYTFmMDk0XkEyXkFqcGc@._V1_.jpg', 'Revolucionó los efectos visuales.', 6.5, 'Un hacker aprende de misteriosos rebeldes sobre la verdadera naturaleza de su realidad y su papel en la guerra contra sus controladores.', 'PELICULA', 'The Matrix', 's008');
INSERT INTO public.producciones VALUES ('pr024', 2, 195, '1997-12-19', 'https://m.media-amazon.com/images/I/811lT7khIrL.jpg', 'Ganadora de 11 premios Oscar.', 6.5, 'Una aristócrata de 17 años se enamora de un artista amable pero pobre a bordo del lujoso e infortunado R.M.S. Titanic.', 'PELICULA', 'Titanic', NULL);
INSERT INTO public.producciones VALUES ('pr025', 3, 155, '2000-05-05', 'https://m.media-amazon.com/images/I/51GA6V6VE1L._AC_UF894,1000_QL80_.jpg', 'Ganadora de 5 premios Oscar.', 6.5, 'Un ex general romano busca venganza contra el corrupto emperador que asesinó a su familia y lo envió a la esclavitud.', 'PELICULA', 'Gladiator', NULL);
INSERT INTO public.producciones VALUES ('pr026', 3, 142, '1994-09-23', 'https://pics.filmaffinity.com/Cadena_perpetua-576140557-large.jpg', 'Basada en la novela de Stephen King.', 6.5, 'Dos hombres encarcelados se vinculan durante varios años, encontrando consuelo y eventual redención a través de actos de decencia común.', 'PELICULA', 'The Shawshank Redemption', NULL);
INSERT INTO public.producciones VALUES ('pr027', 3, 202, '1974-12-20', 'https://s3.amazonaws.com/nightjarprod/content/uploads/sites/192/2022/10/17140449/hek3koDUyRQk7FIhPXsa6mT2Zc3.jpg', 'Secuela de El Padrino.', 6.5, 'La temprana vida y carrera de Vito Corleone en 1920 es representada mientras su hijo, Michael, expande y refuerza su control sobre el sindicato del crimen familiar.', 'PELICULA', 'The Godfather Part II', 's006');
INSERT INTO public.producciones VALUES ('pr028', 2, 201, '2003-12-17', 'https://m.media-amazon.com/images/M/MV5BMTZkMjBjNWMtZGI5OC00MGU0LTk4ZTItODg2NWM3NTVmNWQ4XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', 'Tercera parte de la trilogía.', 6.5, 'Gandalf y Aragorn lideran el Mundo de los Hombres contra el ejército de Sauron para distraer su atención de Frodo y Sam mientras se acercan al Monte del Destino con el Anillo Único.', 'PELICULA', 'The Lord of the Rings: The Return of the King', 's001');
INSERT INTO public.producciones VALUES ('pr029', 2, 169, '2014-11-07', 'https://image.tmdb.org/t/p/w500/gEU2QniE6E77NI6lCU6MxlNBvIx.jpg', 'Dirigida por Christopher Nolan.', 6.5, 'Un equipo de exploradores viaja a través de un agujero de gusano en el espacio en un intento por asegurar la supervivencia de la humanidad.', 'PELICULA', 'Interstellar', NULL);
INSERT INTO public.producciones VALUES ('pr030', 3, 106, '2014-10-15', 'https://image.tmdb.org/t/p/w500/oPxnRhyAIzJKGUEdSiwTJQBa3NM.jpg', 'Ganadora de 3 premios Oscar.', 6.5, 'Un joven baterista ambicioso se inscribe en un conservatorio de música donde su instructor abusivo no se detendrá ante nada para hacer que un estudiante alcance la grandeza.', 'PELICULA', 'Whiplash', NULL);
INSERT INTO public.producciones VALUES ('pr031', 2, 128, '2016-12-09', 'https://image.tmdb.org/t/p/w500/uDO8zWDhfWwoFdKS4fzkUJt0Rf0.jpg', 'Ganadora de 6 premios Oscar.', 6.5, 'Mientras navegan por sus carreras en Los Ángeles, un pianista y una actriz se enamoran mientras intentan reconciliar sus aspiraciones para el futuro.', 'PELICULA', 'La La Land', NULL);
INSERT INTO public.producciones VALUES ('pr032', 4, 165, '2012-12-25', 'https://image.tmdb.org/t/p/w500/7oWY8VDWW7thTzWh3OKYRkWUlD5.jpg', 'Dirigida por Quentin Tarantino.', 6.5, 'Con la ayuda de un cazarrecompensas alemán, un esclavo liberado se embarca en una misión para rescatar a su esposa de un brutal propietario de una plantación en Mississippi.', 'PELICULA', 'Django Desencadenado', 's010');
INSERT INTO public.producciones VALUES ('pr033', 2, 115, '1981-06-12', 'https://m.media-amazon.com/images/M/MV5BNjEwNjY0ZTAtMjk0MS00MDhkLTkwYWUtMjM3ZmI2M2JhYjJhXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', 'Dirigida por Steven Spielberg', 6.5, 'El arqueólogo Indiana Jones busca el Arca de la Alianza', 'PELICULA', 'Indiana Jones y los cazadores del arca perdida', 's012');
INSERT INTO public.producciones VALUES ('pr034', 2, 127, '1993-06-11', 'https://i.pinimg.com/736x/51/ba/64/51ba64b2e61f820e0e86bdd2f4c6e92c.jpg', 'Basada en la novela de Michael Crichton', 6.5, 'Un parque temático con dinosaurios clonados sale mal', 'PELICULA', 'Jurassic Park', 's013');
INSERT INTO public.producciones VALUES ('pr035', 2, 110, '1996-05-22', 'https://m.media-amazon.com/images/S/pv-target-images/1b642f970195bc58824ddcb57315348cf896e4468dc10ab61a8e7ff537e40d67.jpg', 'Primera película de la saga', 6.5, 'Ethan Hunt es acusado de traición y debe limpiar su nombre', 'PELICULA', 'Misión Imposible', 's014');
INSERT INTO public.producciones VALUES ('pr036', 3, 106, '2001-06-22', 'https://www.universalpictures.es/tl_files/content/movies/fast9/fast9_header_mobile.jpg', 'Inicio de la franquicia', 6.5, 'Un policía se infiltra en el mundo de las carreras callejeras', 'PELICULA', 'Fast & Furious', 's015');
INSERT INTO public.producciones VALUES ('pr037', 4, 118, '1991-02-14', 'https://m.media-amazon.com/images/I/61DMhNjjJ3L._AC_UF894,1000_QL80_.jpg', 'Ganadora de 5 Oscars', 6.5, 'Una agente del FBI busca ayuda de un asesino en serie', 'PELICULA', 'El silencio de los corderos', NULL);
INSERT INTO public.producciones VALUES ('pr038', 4, 139, '1999-10-15', 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjptGkW4UwD3BdMJMcAPCcuYD9U9M8GJD3QQ76FIanqoxspZk2q9sdKXSOIx7yiQsF5T-ZdkTHUM21_AEN6vH2OXucUbTnIhQ4CEUbMtWr7TZ-FIklXl5vrGg1fl7vib3E2of5DWCGmE3H3/s2048/Club-de-la-lucha.jpg', 'Basada en la novela de Chuck Palahniuk', 6.5, 'Un oficinista y un vendedor forman un club de lucha subterráneo', 'PELICULA', 'El club de la lucha', NULL);
INSERT INTO public.producciones VALUES ('pr100', 2, 126, '2008-05-02', 'https://m.media-amazon.com/images/M/MV5BMTczNTI2ODUwOF5BMl5BanBnXkFtZTcwMTU0NTIzMw@@._V1_.jpg', 'Primera película del MCU que estableció el tono para el universo compartido.', 7.9, 'Tony Stark, un industrial multimillonario y genio inventor, es secuestrado y obligado a construir un arma devastadora. En su lugar, usando su inteligencia e ingenio, construye una armadura de alta tecnología y escapa de su cautiverio.', 'PELICULA', 'Iron Man', 's100');
INSERT INTO public.producciones VALUES ('pr101', 2, 112, '2008-06-13', 'https://m.media-amazon.com/images/M/MV5BMTUyNzk3MjA1OF5BMl5BanBnXkFtZTcwMTE1Njg2MQ@@._V1_.jpg', 'La única película de Hulk en el MCU con Edward Norton como Bruce Banner.', 6.6, 'Bruce Banner busca una cura para su condición de Hulk mientras es perseguido por el ejército y se enfrenta a un nuevo enemigo, el Abominación.', 'PELICULA', 'The Incredible Hulk', 's100');
INSERT INTO public.producciones VALUES ('pr102', 2, 124, '2010-05-07', 'https://m.media-amazon.com/images/M/MV5BMTM0MDgwNjMyMl5BMl5BanBnXkFtZTcwNTg3NzAzMw@@._V1_.jpg', 'Introdujo a Black Widow y profundizó en la historia de Tony Stark.', 6.9, 'Con el mundo ahora consciente de que él es Iron Man, Tony Stark debe enfrentarse a nuevos enemigos mientras lidia con su salud en declive.', 'PELICULA', 'Iron Man 2', 's100');
INSERT INTO public.producciones VALUES ('pr103', 2, 115, '2011-05-06', 'https://m.media-amazon.com/images/M/MV5BOGE4NzU1YTAtNzA3Mi00ZTA2LTg2YmYtMDJmMThiMjlkYjg2XkEyXkFqcGdeQXVyNTgzMDMzMTg@._V1_.jpg', 'Presentó el mundo de Asgard y el concepto de los Nueve Reinos.', 7, 'El poderoso Thor es desterrado de Asgard y enviado a vivir entre los humanos en la Tierra, donde aprende lo que se necesita para ser un verdadero héroe.', 'PELICULA', 'Thor', 's100');
INSERT INTO public.producciones VALUES ('pr104', 2, 124, '2011-07-22', 'https://m.media-amazon.com/images/M/MV5BMTYzOTc2NzU3N15BMl5BanBnXkFtZTcwNjY3MDE3NQ@@._V1_.jpg', 'Película de época que estableció los orígenes del Capitán América.', 6.9, 'Durante la Segunda Guerra Mundial, Steve Rogers, un hombre débil pero de gran corazón, se transforma en el supersoldado Capitán América para luchar contra las fuerzas de HYDRA.', 'PELICULA', 'Captain America: The First Avenger', 's100');
INSERT INTO public.producciones VALUES ('pr105', 2, 143, '2012-05-04', 'https://m.media-amazon.com/images/M/MV5BNDYxNjQyMjAtNTdiOS00NGYwLWFmNTAtNThmYjU5ZGI2YTI1XkEyXkFqcGdeQXVyMTMxODk2OTU@._V1_.jpg', 'Primera película crossover del MCU que unió a los héroes principales.', 8, 'Nick Fury recluta a un equipo de superhéroes para salvar al mundo de la destrucción inminente cuando Loki intenta conquistar la Tierra.', 'PELICULA', 'The Avengers', 's100');
INSERT INTO public.producciones VALUES ('pr106', 2, 130, '2013-05-03', 'https://m.media-amazon.com/images/M/MV5BMjE5MzcyNjk1M15BMl5BanBnXkFtZTcwMjQ4MjcxOQ@@._V1_.jpg', 'Exploró el trauma de Tony Stark después de los eventos de The Avengers.', 7.1, 'Cuando Tony Stark se enfrenta a un enemigo cuyo alcance no conoce límites, se embarca en una angustiosa búsqueda para destruir a los responsables.', 'PELICULA', 'Iron Man 3', 's100');
INSERT INTO public.producciones VALUES ('pr107', 2, 112, '2013-11-08', 'https://comicsen8mm.com/wp-content/uploads/2013/09/Thor-TDW-Poster-09.jpg', 'Introdujo la Gema de la Realidad y profundizó en la mitología de Thor.', 6.8, 'Thor se une a Loki para salvar los Nueve Reinos de un enemigo más antiguo que el universo mismo mientras Jane Foster descubre una misteriosa sustancia llamada Aether.', 'PELICULA', 'Thor: The Dark World', 's100');
INSERT INTO public.producciones VALUES ('pr108', 2, 136, '2014-04-04', 'https://m.media-amazon.com/images/M/MV5BMzA2NDkwODAwM15BMl5BanBnXkFtZTgwODk5MTgzMTE@._V1_.jpg', 'Película de espionaje que cambió el status quo del MCU.', 7.7, 'Steve Rogers lucha por exponer una conspiración mientras se enfrenta a un asesino misterioso conocido como el Soldado del Invierno.', 'PELICULA', 'Captain America: The Winter Soldier', 's100');
INSERT INTO public.producciones VALUES ('pr109', 2, 121, '2014-08-01', 'https://m.media-amazon.com/images/M/MV5BMTAwMjU5OTgxNjZeQTJeQWpwZ15BbWU4MDUxNDYxODEx._V1_.jpg', 'Expandió el MCU al cosmos con un tono más humorístico.', 8, 'Un grupo de inadaptados intergalácticos se unen para proteger una poderosa gema del malvado Ronan.', 'PELICULA', 'Guardians of the Galaxy', 's100');
INSERT INTO public.producciones VALUES ('pr110', 2, 141, '2015-05-01', 'https://m.media-amazon.com/images/M/MV5BMTM4OGJmNWMtOTM4Ni00NTE3LTg3MDItZmQxYjc4N2JhNmUxXkEyXkFqcGdeQXVyNTgzMDMzMTg@._V1_.jpg', 'Introdujo a Visión, Bruja Escarlata y profundizó en las relaciones entre los héroes.', 7.3, 'Los Vengadores se enfrentan a Ultron, una inteligencia artificial creada por Tony Stark que amenaza con destruir la humanidad.', 'PELICULA', 'Avengers: Age of Ultron', 's100');
INSERT INTO public.producciones VALUES ('pr111', 2, 117, '2015-07-17', 'https://m.media-amazon.com/images/M/MV5BMjM2NTQ5Mzc2M15BMl5BanBnXkFtZTgwNTcxMDI2NTE@._V1_.jpg', 'Película más pequeña en escala pero importante para el MCU.', 7.3, 'Un ladrón con la capacidad de encogerse en tamaño pero aumentar en fuerza debe ayudar a su mentor a proteger el secreto de su traje y salvar al mundo.', 'PELICULA', 'Ant-Man', 's100');
INSERT INTO public.producciones VALUES ('pr112', 2, 147, '2016-05-06', 'https://m.media-amazon.com/images/M/MV5BMjQ0MTgyNjAxMV5BMl5BanBnXkFtZTgwNjUzMDkyODE@._V1_.jpg', 'Introdujo a Black Panther y Spider-Man en el MCU.', 7.8, 'Los Vengadores se dividen en dos bandos, uno liderado por Steve Rogers y otro por Tony Stark, debido a un desacuerdo sobre la supervisión gubernamental.', 'PELICULA', 'Captain America: Civil War', 's100');
INSERT INTO public.producciones VALUES ('pr113', 2, 115, '2016-11-04', 'https://m.media-amazon.com/images/M/MV5BNjgwNzAzNjk1Nl5BMl5BanBnXkFtZTgwMzQ2NjI1OTE@._V1_.jpg', 'Introdujo la magia y las dimensiones alternativas al MCU.', 7.5, 'Un neurocirujano arrogante aprende los secretos de las artes místicas después de un accidente que destruye su carrera.', 'PELICULA', 'Doctor Strange', 's100');
INSERT INTO public.producciones VALUES ('pr114', 2, 136, '2017-05-05', 'https://m.media-amazon.com/images/M/MV5BMTg2MzI1MTg3OF5BMl5BanBnXkFtZTgwNTU3NDA2MTI@._V1_.jpg', 'Profundizó en los personajes y su dinámica familiar.', 7.6, 'Los Guardianes luchan por mantenerse unidos mientras descubren los secretos del verdadero padre de Peter Quill.', 'PELICULA', 'Guardians of the Galaxy Vol. 2', 's100');
INSERT INTO public.producciones VALUES ('pr115', 2, 133, '2017-07-07', 'https://m.media-amazon.com/images/M/MV5BNTk4ODQ1MzgzNl5BMl5BanBnXkFtZTgwMTMyMzM4MTI@._V1_.jpg', 'Primera película de Spider-Man en el MCU.', 7.4, 'Peter Parker equilibra su vida como estudiante de secundaria con ser Spider-Man mientras se enfrenta al Buitre.', 'PELICULA', 'Spider-Man: Homecoming', 's100');
INSERT INTO public.producciones VALUES ('pr116', 2, 130, '2017-11-03', 'https://m.media-amazon.com/images/M/MV5BMjMyNDkzMzI1OF5BMl5BanBnXkFtZTgwODcxODg5MjI@._V1_.jpg', 'Cambió el tono de las películas de Thor a un estilo más cómico.', 7.9, 'Thor está atrapado en el otro lado del universo y debe luchar por su vida en una carrera de gladiadores para salvar a su pueblo de la poderosa Hela.', 'PELICULA', 'Thor: Ragnarok', 's100');
INSERT INTO public.producciones VALUES ('pr117', 2, 134, '2018-02-16', 'https://m.media-amazon.com/images/M/MV5BMTg1MTY2MjYzNV5BMl5BanBnXkFtZTgwMTc4NTMwNDI@._V1_.jpg', 'Primera película de superhéroes negros nominada al Oscar a Mejor Película.', 7.3, 'TChalla, rey de Wakanda, debe defender su nación y su legado cuando un viejo enemigo reaparece.', 'PELICULA', 'Black Panther', 's100');
INSERT INTO public.producciones VALUES ('pr118', 2, 149, '2018-04-27', 'https://m.media-amazon.com/images/M/MV5BMjMxNjY2MDU1OV5BMl5BanBnXkFtZTgwNzY1MTUwNTM@._V1_.jpg', 'Primera parte del clímax de la Saga del Infinito.', 8.4, 'Los Vengadores y sus aliados deben estar dispuestos a sacrificarlo todo para derrotar al poderoso Thanos antes de que su ataque de devastación y ruina acabe con el universo.', 'PELICULA', 'Avengers: Infinity War', 's100');
INSERT INTO public.producciones VALUES ('pr119', 2, 118, '2018-07-06', 'https://m.media-amazon.com/images/M/MV5BYjcyYTk0N2YtMzc4ZC00Y2E0LWFkNDgtNjE1MzZmMGE1YjY1XkEyXkFqcGdeQXVyMTMxODk2OTU@._V1_.jpg', 'Película más ligera después del intenso final de Infinity War.', 7, 'Scott Lang lucha por equilibrar su vida como padre y como Ant-Man mientras Hope van Dyne y el Dr. Hank Pym lo reclaman para una nueva misión urgente.', 'PELICULA', 'Ant-Man and the Wasp', 's100');
INSERT INTO public.producciones VALUES ('pr120', 2, 124, '2019-03-08', 'https://m.media-amazon.com/images/M/MV5BMTE0YWFmOTMtYTU2ZS00ZTIxLWE3OTEtYTNiYzBkZjViZThiXkEyXkFqcGdeQXVyODMzMzQ4OTI@._V1_.jpg', 'Primera película del MCU protagonizada por una mujer.', 6.8, 'Carol Danvers se convierte en uno de los héroes más poderosos del universo cuando la Tierra queda atrapada en medio de una guerra galáctica entre dos razas alienígenas.', 'PELICULA', 'Captain Marvel', 's100');
INSERT INTO public.producciones VALUES ('pr121', 2, 181, '2019-04-26', 'https://m.media-amazon.com/images/M/MV5BMTc5MDE2ODcwNV5BMl5BanBnXkFtZTgwMzI2NzQ2NzM@._V1_.jpg', 'Avengers: Endgame (Vengadores: Endgame en España es una película de superhéroes estadounidense de 2019 basada en el equipo de superhéroes de Marvel Comics, Los Vengadores. Producida por Marvel Studios y distribuida por Walt Disney Studios Motion Pictures, es la secuela directa de Avengers: Infinity War (2018) y la película número 22 del Universo cinematográfico de Marvel (UCM), y hasta la fecha la más larga. Dirigida por Anthony y Joe Russo y escrita por Christopher Markus y Stephen McFeely, la película cuenta con un reparto coral que incluye a Robert Downey Jr., Chris Evans, Mark Ruffalo, Chris Hemsworth, Scarlett Johansson, Jeremy Renner, Don Cheadle, Paul Rudd, Brie Larson, Karen Gillan, Danai Gurira, Benedict Wong, Jon Favreau, Bradley Cooper, Gwyneth Paltrow y Josh Brolin. En la película, los miembros supervivientes de los Vengadores y sus aliados intentan revertir el daño causado por Thanos en Infinity War.', 8.4, 'Después de los eventos devastadores de "Avengers: Infinity War", el universo está en ruinas debido a las acciones de Thanos, el Titán Loco. Con la ayuda de los aliados que quedaron, los Vengadores deberán reunirse una vez más para intentar detenerlo y restaurar el orden en el universo de una vez por todas.', 'PELICULA', 'Avengers: Endgame', 's100');
INSERT INTO public.producciones VALUES ('pr122', 2, 129, '2019-07-02', 'https://m.media-amazon.com/images/M/MV5BMGZlNTY1ZWUtYTMzNC00ZjUyLWE0MjQtMTMxN2E3ODYxMWVmXkEyXkFqcGdeQXVyMDM2NDM2MQ@@._V1_.jpg', 'Primera película del MCU después de Endgame.', 7.4, 'Peter Parker va de vacaciones a Europa con sus amigos, pero su plan de dejar de ser Spider-Man por un tiempo se ve interrumpido cuando Nick Fury lo reclama para una misión.', 'PELICULA', 'Spider-Man: Far From Home', 's100');
INSERT INTO public.producciones VALUES ('pr123', 3, 134, '2021-07-09', 'https://m.media-amazon.com/images/M/MV5BNjRmNDI5MjMtMmFhZi00YzcwLWI4ZGItMGI2MjI0N2Q3YmIwXkEyXkFqcGdeQXVyMTkxNjUyNQ@@._V1_.jpg', 'Primera película en solitario de Black Widow.', 6.7, 'Natasha Romanoff se enfrenta a las partes más oscuras de su historia cuando surge una peligrosa conspiración relacionada con su pasado.', 'PELICULA', 'Black Widow', 's100');
INSERT INTO public.producciones VALUES ('pr124', 2, 132, '2021-09-03', 'https://m.media-amazon.com/images/M/MV5BNTliYjlkNDQtMjFlNS00NjgzLWFmMWEtYmM2Mzc2Zjg3ZjEyXkEyXkFqcGdeQXVyMTkxNjUyNQ@@._V1_.jpg', 'Primera película del MCU protagonizada por un superhéroe asiático.', 7.4, 'Shang-Chi, un maestro de artes marciales, se ve arrastrado al misterioso mundo de los Diez Anillos.', 'PELICULA', 'Shang-Chi and the Legend of the Ten Rings', 's100');
INSERT INTO public.producciones VALUES ('pr125', 2, 156, '2021-11-05', 'https://m.media-amazon.com/images/M/MV5BMTExZmVjY2ItYTAzYi00MDdlLWFlOWItNTJhMDRjMzQ5ZGY0XkEyXkFqcGdeQXVyODIyOTEyMzY@._V1_.jpg', 'Introdujo un nuevo grupo de héroes cósmicos al MCU.', 6.3, 'Los Eternos, una raza de seres inmortales, emergen de las sombras para proteger a la Tierra de sus antiguos enemigos, los Deviants.', 'PELICULA', 'Eternals', 's100');
INSERT INTO public.producciones VALUES ('pr126', 2, 148, '2021-12-17', 'https://m.media-amazon.com/images/M/MV5BZWMyYzFjYTYtNTRjYi00OGExLWE2YzgtOGRmYjAxZTU3NzBiXkEyXkFqcGdeQXVyMzQ0MzA0NTM@._V1_.jpg', 'Película crossover que unió a múltiples versiones de Spider-Man.', 8.2, 'Peter Parker pide ayuda al Doctor Strange para que el mundo olvide que es Spider-Man, pero el hechizo sale mal y abre el multiverso.', 'PELICULA', 'Spider-Man: No Way Home', 's100');
INSERT INTO public.producciones VALUES ('pr127', 3, 126, '2022-05-06', 'https://m.media-amazon.com/images/M/MV5BNWM0ZGJlMzMtZmYwMi00NzI3LTgzMzMtNjMzNjliNDRmZmFlXkEyXkFqcGdeQXVyMTM1MTE1NDMx._V1_.jpg', 'Primera película de terror del MCU dirigida por Sam Raimi.', 6.9, 'El Doctor Strange viaja a través de realidades alternativas para enfrentarse a una nueva y misteriosa amenaza.', 'PELICULA', 'Doctor Strange in the Multiverse of Madness', 's100');
INSERT INTO public.producciones VALUES ('pr128', 3, 119, '2022-07-08', 'https://m.media-amazon.com/images/M/MV5BYmMxZWRiMTgtZjM0Ny00NDQxLWIxYWQtZDdlNDNkOTEzYTdlXkEyXkFqcGdeQXVyMTkxNjUyNQ@@._V1_.jpg', 'Cuarta película en solitario de Thor con Natalie Portman como Thor.', 6.2, 'Thor intenta encontrar la paz interior, pero debe regresar a la acción para detener a Gorr el Dios Carnicero.', 'PELICULA', 'Thor: Love and Thunder', 's100');
INSERT INTO public.producciones VALUES ('pr129', 3, 161, '2022-11-11', 'https://m.media-amazon.com/images/M/MV5BNTM4NjIxNmEtYWE5NS00NDczLTkyNWQtYThhNmQyZGQzMjM0XkEyXkFqcGdeQXVyODk4OTc3MTY@._V1_.jpg', 'Homenaje a Chadwick Boseman y continuación de la historia de Wakanda.', 6.7, 'El pueblo de Wakanda lucha por proteger su nación de las potencias mundiales tras la muerte del rey TChalla.', 'PELICULA', 'Black Panther: Wakanda Forever', 's100');
INSERT INTO public.producciones VALUES ('pr130', 2, 125, '2023-02-17', 'https://m.media-amazon.com/images/M/MV5BODZhNzlmOGItMWUyYS00Y2Q5LWFlNzMtM2I2NDFkM2ZkYmE1XkEyXkFqcGdeQXVyMTU5OTA4NTIz._V1_.jpg', 'Introdujo a Kang como el nuevo gran villano del MCU.', 6.1, 'Scott Lang y Hope van Dyne son arrastrados al Reino Cuántico, donde se enfrentan a Kang el Conquistador.', 'PELICULA', 'Ant-Man and the Wasp: Quantumania', 's100');
INSERT INTO public.producciones VALUES ('pr131', 3, 150, '2023-05-05', 'https://www.dolby.com/siteassets/xf-site/content-detail-pages/gotg_1280x1920.jpg', 'Conclusión de la trilogía de Guardianes de la Galaxia.', 8, 'Los Guardianes protegen a uno de los suyos mientras buscan completar su misión final.', 'PELICULA', 'Guardians of the Galaxy Vol. 3', 's100');
INSERT INTO public.producciones VALUES ('pr132', 2, 105, '2023-11-10', 'https://www.pantalla90.es/wp-content/uploads/2023/11/nuevo-poster-de-the-marvels-original.jpg', 'Secuela de Captain Marvel que une a tres heroínas.', 5.8, 'Carol Danvers, Monica Rambeau y Kamala Khan deben trabajar juntas cuando sus poderes se entrelazan.', 'PELICULA', 'The Marvels', 's100');
INSERT INTO public.producciones VALUES ('pr133', 3, 4200, '2011-04-17', 'https://m.media-amazon.com/images/M/MV5BN2IzYzBiOTQtNGZmMi00NDI5LTgxMzMtN2EzZjA1NjhlOGMxXkEyXkFqcGdeQXVyNjAwNDUxODI@._V1_.jpg', 'Serie de televisión basada en la saga de novelas "Canción de hielo y fuego" de George R.R. Martin. La serie se convirtió en un fenómeno cultural y ganó numerosos premios Emmy.', 9.2, 'En un mundo donde las estaciones duran años, varias familias nobles luchan por el control del Trono de Hierro del continente de Poniente. Mientras, una antigua amenaza resurge en el norte y una joven exiliada reclama su legítimo lugar en el sur.', 'SERIE', 'Juego de Tronos', 's016');
INSERT INTO public.producciones VALUES ('pr134', 3, 600, '2022-08-21', 'https://m.media-amazon.com/images/M/MV5BZjBiOGIyY2YtOTA3OC00YzY1LThkYjktMGRkYTNhNTExY2I2XkEyXkFqcGdeQXVyMTEyMjM2NDc2._V1_.jpg', 'Basada en partes de la novela "Fire & Blood" de George R.R. Martin, la serie explora el apogeo de la dinastía Targaryen en Poniente.', 8.5, 'Prequela de "Juego de Tronos" que narra la historia de la Casa Targaryen, 200 años antes de los eventos de la serie original, centrándose en la Danza de los Dragones, una guerra civil por la sucesión al Trono de Hierro.', 'SERIE', 'La Casa del Dragón', 's016');
INSERT INTO public.profesionales VALUES ('p001', 'Dos veces ganador del Oscar, conocido por Forrest Gump y Toy Story.', '1978-01-01', '1956-07-09', 'https://encrypted-tbn1.gstatic.com/images?q=tbn:ANd9GcRMbEBRIFN_A3mQS7etzyoVo7UGJ8Xr3xMS1KmMaujuH7qDKttQdWs74OoYRgIj3C7OR0YRzTbjsSLL0VMXXLy_ug', 'Concord, California, USA', 'Tom Hanks');
